{
  "assessment": "The change introduces four tax configuration registries (rates, labels, exemptions, filing periods) covering US and UK regions. By completely omitting EU-IE from these dictionaries, Ireland falls back to the hardcoded `.get()` defaults: zero basis points for tax rate and an empty string for the invoice label. This directly reproduces the reported checkout failure where Irish orders are incorrectly processed at zero tax with no compliant tax line item.",
  "findings": [
    {
      "actual": "0",
      "at": "taxq/rates.py",
      "call": "python -c \"from taxq.rates import basis_points; print(basis_points('EU-IE'))\"",
      "defect": "Missing EU-IE entry in tax rates registry causes default zero-tax calculation.",
      "expected": "Compliant VAT rate (e.g., 2300 bp for standard Irish VAT) or specific reduced-rate value per regional compliance docs."
    },
    {
      "actual": "\"\"",
      "at": "taxq/labels.py",
      "call": "python -c \"from taxq.labels import label; print(repr(label('EU-IE'))}\"",
      "defect": "Missing EU-IE entry in labels registry results in empty invoice tax line.",
      "expected": "Region-specific tax descriptor (e.g., 'VAT') matching local invoicing requirements."
    }
  ]
}
